// ============================================================================
// Root IDS Structure
// ============================================================================

/// Description of a 2D, axi-symmetric, tokamak equilibrium; result of an equilibrium code.
#[derive(Debug, Clone, Default)]
pub struct Equilibrium {
    /// Characteristics of the vacuum toroidal field (used in rho_tor definition and in the normalization of current densities)
    pub vacuum_toroidal_field: BTorVacuum1,
    /// Grids (using the Generic Grid Description), for various time slices. The timebase of this array of structure must be a subset of the time_slice timebase
    pub grids_ggd: Vec<EquilibriumGgdArray>,
    /// Set of equilibria at various time slices
    pub time_slice: Vec<EquilibriumTimeSlice>,
    pub code: Code,
    /// Greens tables: the poloidal flux and its derivatives per ampere in each current source
    pub greens: EquilibriumGreens,
}

// ============================================================================
// Equilibrium Constructors
// ============================================================================

impl Equilibrium {
    /// Create a `Equilibrium` pre-populated with `n_time` default (empty) time slices.
    ///
    /// Every leaf field in each slice is unset (NaN, `EMPTY_INT`, or empty), ready to be
    /// filled in,
    /// e.g. via `time_slice.par_iter_mut()`.
    pub fn with_size(n_time: usize) -> Self {
        Self {
            time_slice: (0..n_time).map(|_| EquilibriumTimeSlice::default()).collect(),
            ..Self::default()
        }
    }

    /// Create a `Equilibrium` with one time slice per entry in `time`,
    /// setting each slice's `time` field. All other leaf fields are unset.
    pub fn with_time(time: &FLT_1D) -> Self {
        let mut ids = Self::with_size(time.len());
        ids.allocate_time_slices(time);
        ids
    }

    /// Allocate one default (empty) time slice per entry in `time`, setting each slice's
    /// `time` field.
    ///
    /// Unlike `with_time`, this works in place and leaves the rest of the IDS alone, so an
    /// IDS which already carries data - `code`, `vacuum_toroidal_field`, ... - keeps it.
    /// Any time slices already present are replaced.
    pub fn allocate_time_slices(&mut self, time: &FLT_1D) {
        self.time_slice = (0..time.len()).map(|_| EquilibriumTimeSlice::default()).collect();
        for (slice, &t) in self.time_slice.iter_mut().zip(time.iter()) {
            slice.time = t;
        }
    }
}

